def creer_valeurs(apps, schema_editor):
    V = apps.get_model("beneficiaire", "ValeurListe")
    for liste, libelles in VALEURS.items():
        for i, libelle in enumerate(libelles, 1):
            V.objects.get_or_create(liste=liste, libelle=libelle, defaults={"ordre": i * 10})


